//! The element metadata of HTML: `data/elements.txt` (generated by `data/generate.mjs`), sections
//! `[name]` followed by whitespace-separated items. Parsed on first use.

use std::collections::{HashMap, HashSet};
use std::sync::LazyLock;

static TABLES: LazyLock<HashMap<&'static str, HashSet<&'static str>>> = LazyLock::new(|| {
    let mut tables: HashMap<_, HashSet<_>> = HashMap::new();
    let mut section = "";
    for line in include_str!("../data/elements.txt").lines() {
        match line.strip_prefix('[').and_then(|l| l.strip_suffix(']')) {
            Some(name) => section = name,
            None if line.starts_with('#') => {}
            None => tables
                .entry(section)
                .or_default()
                .extend(line.split_whitespace()),
        }
    }
    tables
});

/// Whether lowercase `name` is in `section`.
pub fn has(section: &str, name: &str) -> bool {
    TABLES.get(section).is_some_and(|s| s.contains(name))
}

/// Whether `attr` of `element` carries the flag `section`: a bare name is global, `element:attr`
/// is one element's.
pub fn flagged(section: &str, element: &str, attr: &str) -> bool {
    has(section, attr) || has(section, &format!("{element}:{attr}"))
}

/// The attributes `element` must have.
pub fn required(element: &str) -> impl Iterator<Item = &'static str> {
    let prefix = format!("{element}:");
    TABLES
        .get("required")
        .into_iter()
        .flatten()
        .filter_map(move |i| i.strip_prefix(prefix.as_str()))
}

/// The values `attr` of `element` is limited to, when the metadata lists them (`[enum]` items are
/// `[element,element:]attribute=value|value`; an item for the element wins over a global one).
pub fn allowed(element: &str, attr: &str) -> Option<Vec<&'static str>> {
    let items = || TABLES.get("enum").into_iter().flatten();
    let found = |specific: bool| {
        items().find_map(|i| {
            let (key, values) = i.split_once('=')?;
            let hit = match key.rsplit_once(':') {
                Some((elements, a)) => {
                    specific && a == attr && elements.split(',').any(|e| e == element)
                }
                None => !specific && key == attr,
            };
            hit.then(|| values.split('|').collect())
        })
    };
    found(true).or_else(|| found(false))
}
